    public static func image(for id: String?) -> NSImage? {
        guard let id = id?.lowercased().trimmingCharacters(in: .whitespaces), !id.isEmpty else {
            return nil
        }
        let key = id as NSString
        if let cached = cache.object(forKey: key) {
            return cached
        }
        guard let item = allIcons.first(where: { $0.id == id }) else {
            return nil
        }

        if let sym = item.systemSymbol, let symImg = NSImage(systemSymbolName: sym, accessibilityDescription: item.title) {
            symImg.size = NSSize(width: 16, height: 16)
            cache.setObject(symImg, forKey: key)
            return symImg
        }

        guard let data = item.svg.data(using: .utf8),
              let img = NSImage(data: data) else {
            return nil
        }
        img.size = NSSize(width: 16, height: 16)
        cache.setObject(img, forKey: key)
        return img
    }

    /// Smart default icon detection by matching keywords in group name
    public static func defaultIcon(for groupName: String) -> String? {
        let lower = groupName.lowercased()
        if lower.contains("cisco") { return "cisco" }
        if lower.contains("fortinet") || lower.contains("forti") { return "fortinet" }
        if lower.contains("redhat") || lower.contains("rhel") || lower.contains("red hat") { return "redhat" }
        if lower.contains("ubuntu") { return "ubuntu" }
        if lower.contains("debian") { return "debian" }
        if lower.contains("centos") { return "centos" }
        if lower.contains("linux") { return "linux" }
        if lower.contains("docker") { return "docker" }
        if lower.contains("kube") || lower.contains("k8s") { return "kubernetes" }
        if lower.contains("ansible") { return "ansible" }
        if lower.contains("terraform") { return "terraform" }
        if lower.contains("nginx") { return "nginx" }
        if lower.contains("postgres") || lower.contains("psql") { return "postgres" }
        if lower.contains("redis") { return "redis" }
        if lower.contains("cloudflare") { return "cloudflare" }
        if lower.contains("wireguard") || lower.contains("vpn") { return "wireguard" }
        if lower.contains("git") { return "github" }
        if lower.contains("python") || lower.contains("py") { return "python" }
        if lower.contains("apple") || lower.contains("mac") { return "apple" }
        if lower.contains("apache") { return "apache" }
        if lower.contains("aws") || lower.contains("amazon") { return "aws" }
        if lower.contains("backup") { return "backup" }
        if lower.contains("cassandra") { return "cassandra" }
        if lower.contains("confluence") { return "confluence" }
        if lower.contains("database") || lower.contains("db") { return "database" }
        if lower.contains("dell") { return "dell" }
        if lower.contains("digitalocean") || lower.contains("ocean") { return "digitalocean" }
        if lower.contains("django") { return "django" }
        if lower.contains("fedora") { return "fedora" }
        if lower.contains("firewall") || lower.contains("fw") { return "firewall" }
        if lower.contains("freebsd") || lower.contains("bsd") { return "freebsd" }
        if lower.contains("ghost") { return "ghost" }
        if lower.contains("glassfish") { return "glassfish" }
        if lower.contains("hadoop") { return "hadoop" }
        if lower.contains("heroku") { return "heroku" }
        return nil
    }
}

public struct IconPickerPopUpButton: NSViewRepresentable {
    @Binding var selectedIcon: String?
    var onSelected: ((String?) -> Void)? = nil

    public init(selectedIcon: Binding<String?>, onSelected: ((String?) -> Void)? = nil) {
        self._selectedIcon = selectedIcon
        self.onSelected = onSelected
    }

    public func makeNSView(context: Context) -> NSPopUpButton {
        let button = NSPopUpButton(frame: .zero, pullsDown: false)
        button.target = context.coordinator
        button.action = #selector(Coordinator.selectionChanged(_:))
        button.controlSize = .regular
        button.font = .systemFont(ofSize: 13)
        context.coordinator.populateMenu(button: button, selected: selectedIcon)
        return button
    }

    public func updateNSView(_ button: NSPopUpButton, context: Context) {
        context.coordinator.parent = self
        context.coordinator.updateSelection(button: button, selected: selectedIcon)
    }

    public func makeCoordinator() -> Coordinator {
        Coordinator(self)
    }

    public class Coordinator: NSObject {
        var parent: IconPickerPopUpButton

        init(_ parent: IconPickerPopUpButton) {
            self.parent = parent
        }

        func populateMenu(button: NSPopUpButton, selected: String?) {
            button.menu?.removeAllItems()

            let defaultItem = NSMenuItem(title: "default", action: nil, keyEquivalent: "")
            defaultItem.representedObject = nil as String?
            if let defImg = NSImage(systemSymbolName: "folder", accessibilityDescription: "default") {
                defImg.size = NSSize(width: 15, height: 15)
                defaultItem.image = defImg
            }
            button.menu?.addItem(defaultItem)

            for icon in GroupIconCatalog.allIcons {
                let item = NSMenuItem(title: icon.title, action: nil, keyEquivalent: "")
                item.representedObject = icon.id
                if let img = GroupIconCatalog.image(for: icon.id) {
                    item.image = img
                }
                button.menu?.addItem(item)
            }
            updateSelection(button: button, selected: selected)
        }

        func updateSelection(button: NSPopUpButton, selected: String?) {
            if let selected = selected {
                if let idx = button.menu?.items.firstIndex(where: { ($0.representedObject as? String) == selected }) {
                    if button.indexOfSelectedItem != idx {
                        button.selectItem(at: idx)
                    }
                    return
                }
            }
            if button.indexOfSelectedItem != 0 {
                button.selectItem(at: 0)
            }
        }

        @objc func selectionChanged(_ sender: NSPopUpButton) {
            let selected = sender.selectedItem?.representedObject as? String
            parent.selectedIcon = selected
            parent.onSelected?(selected)
        }
    }
}
